code_examples.code:
/* element: every h2 */
h2 { color: red; }

/* class: anything with class="red-text" */
.red-text { color: red; }

/* id: the one element with id="main" */
#main { color: red; }

/* attribute: every p that has draggable="false" */
p[draggable="false"] { color: red; }

/* universal: everything */
* { color: red; }

